firmware:
const int LED = 5;
int fades = 0;

void setup() {
  Serial.begin(115200);
  pinMode(LED, OUTPUT);
}

void loop() {
  for (int b = 0; b <= 255; b += 5) {
    analogWrite(LED, b);
    delay(20);
  }
  for (int b = 255; b >= 0; b -= 5) {
    analogWrite(LED, b);
    delay(20);
  }
  if (++fades == 1) Serial.println("FADE");
}
